sys_script_include.script:
var PatientAjaxHelper = Class.create();
PatientAjaxHelper.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getPatientDetails: function () {
        var patientId = this.getParameter('sysparm_patient_id');
        var result = {};

        var gr = new GlideRecord('u_patient_record'); // replace with your table name
        if (gr.get(patientId)) {
            result.name   = gr.getDisplayValue('u_first_name');
            result.gender = gr.getDisplayValue('u_gender');
        } else {
            result.error = "Patient not found";
        }

        return new JSON().encode(result);
    }

});
